<?php defined( 'ABSPATH' ) || exit; do_action( 'woocommerce_before_cart' ); ?><div class="container cart-page"><div class="shop-breadcrumbs"><?php souqify_breadcrumbs(); ?></div><h1><?php esc_html_e( 'Your cart', 'souqify' ); ?></h1><?php if ( WC()->cart->is_empty() ) : ?><div class="empty-state cart-empty"><div class="empty-icon">🛒</div><h2><?php esc_html_e( 'Your cart is empty', 'souqify' ); ?></h2><p><?php esc_html_e( 'Looks like you have not added anything yet.', 'souqify' ); ?></p><a class="button button-primary" href="<?php echo esc_url( wc_get_page_permalink( 'shop' ) ); ?>"><?php esc_html_e( 'Continue shopping', 'souqify' ); ?></a></div><?php else : ?><form class="woocommerce-cart-form" action="<?php echo esc_url( wc_get_cart_url() ); ?>" method="post"><div class="cart-layout"><div class="cart-items"><table class="shop_table shop_table_responsive cart woocommerce-cart-form__contents"><thead><tr><th><?php esc_html_e( 'Product', 'souqify' ); ?></th><th><?php esc_html_e( 'Price', 'souqify' ); ?></th><th><?php esc_html_e( 'Quantity', 'souqify' ); ?></th><th><?php esc_html_e( 'Subtotal', 'souqify' ); ?></th></tr></thead><tbody><?php foreach ( WC()->cart->get_cart() as $cart_item_key => $cart_item ) { $_product = apply_filters( 'woocommerce_cart_item_product', $cart_item['data'], $cart_item, $cart_item_key ); if ( ! $_product || ! $_product->exists() || $cart_item['quantity'] <= 0 ) { continue; } ?><tr class="woocommerce-cart-form__cart-item cart_item"><?php echo '<td class="product-name" data-title="' . esc_attr__( 'Product', 'souqify' ) . '"><div class="cart-product"><a href="' . esc_url( $_product->get_permalink( $cart_item ) ) . '">' . wp_kses_post( $_product->get_image( 'thumbnail' ) ) . '</a><a href="' . esc_url( $_product->get_permalink( $cart_item ) ) . '">' . esc_html( $_product->get_name() ) . '</a></div></td>'; ?><td data-title="<?php esc_attr_e( 'Price', 'souqify' ); ?>"><?php echo wp_kses_post( WC()->cart->get_product_price( $_product ) ); ?></td><td data-title="<?php esc_attr_e( 'Quantity', 'souqify' ); ?>"><?php echo woocommerce_quantity_input( array( 'input_name' => "cart[{$cart_item_key}][qty]", 'input_value' => $cart_item['quantity'], 'min_value' => 0, 'max_value' => $_product->get_max_purchase_quantity() ), $_product, false ); ?></td><td data-title="<?php esc_attr_e( 'Subtotal', 'souqify' ); ?>"><?php echo wp_kses_post( WC()->cart->get_product_subtotal( $_product, $cart_item['quantity'] ) ); ?> <a class="remove" href="<?php echo esc_url( wc_get_cart_remove_url( $cart_item_key ) ); ?>" aria-label="<?php esc_attr_e( 'Remove item', 'souqify' ); ?>">×</a></td></tr><?php } ?></tbody></table><button type="submit" class="button button-outline" name="update_cart" value="1"><?php esc_html_e( 'Update cart', 'souqify' ); ?></button><?php wp_nonce_field( 'woocommerce-cart', 'woocommerce-cart-nonce' ); ?></div><div class="cart-summary"><h2><?php esc_html_e( 'Order summary', 'souqify' ); ?></h2><?php do_action( 'woocommerce_cart_collaterals' ); ?></div></div></form><?php endif; ?></div><?php do_action( 'woocommerce_after_cart' ); ?>
